function validate(input) {
  const [{ Warehouse = [], Products = [] }] = input;
  const products = new Set(), stock = new Set();
  for (const [id, , width, length, height] of Products) {
    if (id === null) return 'Every product needs a product_id.';
    if (products.has(id)) return `product_id ${id} appears twice in Products.`;
    products.add(id);
    for (const side of [width, length, height]) {
      if (side === null || side < 1) return `Product ${id} needs Width, Length and Height of at least 1.`;
    }
  }
  for (const [name, id, units] of Warehouse) {
    if (name === null) return 'Every Warehouse row needs a name.';
    const key = `${String(name).toLowerCase()}|${id}`;
    if (stock.has(key)) return `Warehouse ${name} lists product ${id} twice.`;
    stock.add(key);
    if (!products.has(id)) return `Warehouse ${name} stocks product ${id}, which is not in Products.`;
    if (units === null || units < 0) return `Warehouse ${name} needs a units count of at least 0 for product ${id}.`;
  }
  return null;
}

