function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const small = size === 'small';
  const names = ['LC-TV', 'LC-KeyChain', 'LC-Phone', 'LC-T-Shirt', 'LC-Lamp', 'LC-Desk'];
  const sides = small ? [1, 2, 4, 5, 10] : [1, 2, 3, 5, 10, 20, 40, 50];
  const houses = small ? ['LCHouse1', 'LCHouse2', 'LCHouse3', 'Depot'] : Array.from({ length: 20 }, (_, i) => `House${i + 1}`);
  const unitPool = small ? [0, 1, 1, 2, 5, 10] : [0, 1, 2, 3, 5, 10, 25, 100];
  const productCount = small ? Math.floor(rand() * 6) : 300;
  const Products = [];
  for (let id = 1; id <= productCount; id++) Products.push([id, pick(names), pick(sides), pick(sides), pick(sides)]);
  const Warehouse = [];
  if (productCount > 0) {
    const target = small ? Math.floor(rand() * 9) : 2000;
    const used = new Set();
    // Draw (warehouse, product) pairs until enough distinct ones are found; small pools make repeats likely, so cap attempts.
    for (let tries = 0; Warehouse.length < target && tries < target * 4; tries++) {
      const house = pick(houses), product = 1 + Math.floor(rand() * productCount);
      const key = `${house}|${product}`;
      if (used.has(key)) continue;
      used.add(key);
      Warehouse.push([house, product, pick(unitPool)]);
    }
  }
  return [{ Warehouse, Products }];
}
